package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class WholeFactorExtremaTest {
 private long independentGcd(int a,int b){if(a==0)return b;if(b==0)return a;long greatest=1;for(int d=1;d<=Math.min(a,b);d++)if(a%d==0&&b%d==0)greatest=d;return greatest;}
 private boolean correct(Question q,List<String>answers){q.answers=new String[]{"poison"};q.expression="poison";return WholeFactorExtrema.check(q,answers).correct();}
 @Test public void publicDefinitionsZeroAndLargeCoprimeProducts(){for(String id:List.of("gcd","lcm")){for(int[]pair:new int[][]{{0,0},{0,1},{1,1},{12,18},{18,12},{49,7},{97,99}}){Question q=WholeFactorExtrema.make(id,pair[0],pair[1]);boolean undef=id.equals("gcd")?pair[0]==0&&pair[1]==0:pair[0]==0||pair[1]==0;assertEquals(undef,WholeFactorExtrema.undefined(q));long divisor=independentGcd(pair[0],pair[1]);long expected=id.equals("gcd")?divisor:divisor==0?0:(long)pair[0]/divisor*pair[1];assertTrue(correct(q,undef?List.of(WholeFactorExtrema.NONE):List.of(""+expected)));assertFalse(correct(q,List.of("0")));if(!undef)assertFalse(correct(q,List.of(WholeFactorExtrema.NONE)));}Question large=WholeFactorExtrema.make(id,1000000,999999);assertTrue(correct(large,List.of(id.equals("gcd")?"1":"999999000000")));}
  assertTrue(correct(WholeFactorExtrema.make("gcd",0,0),List.of("draft",WholeFactorExtrema.NONE)));assertTrue(correct(WholeFactorExtrema.make("lcm",0,1),List.of("99",WholeFactorExtrema.NONE)));assertFalse(correct(WholeFactorExtrema.make("gcd",0,1),List.of(WholeFactorExtrema.NONE)));assertFalse(correct(WholeFactorExtrema.make("gcd",12,18),List.of("3")));assertFalse(correct(WholeFactorExtrema.make("lcm",12,18),List.of("72")));assertEquals(Checker.Status.INPUT_NEEDED,WholeFactorExtrema.check(WholeFactorExtrema.make("gcd",0,0),List.of("@no-prime-factors")).status);
 }
 @Test public void indexedUnorderedDomainHasAllConditionsBeforeOldest(){for(String id:List.of("gcd","lcm")){Set<String>independent=new HashSet<>();for(int a=3;a<=5;a++)for(int b=a;b<=5;b++)independent.add(WholeFactorExtrema.make(id,a,b).signature());assertEquals(6,WholeFactorExtrema.count(3,5));Set<String>indexed=new HashSet<>();for(long i=0;i<6;i++)assertTrue(indexed.add(WholeFactorExtrema.indexed(id,i,3,5).signature()));assertEquals(independent,indexed);CurriculumLimits limits=new CurriculumLimits("minGiven=3;maxGiven=5;maxResult=100;nonnegative=true");Map<String,Integer>recent=new LinkedHashMap<>();Random pinned=new Random(){@Override public long nextLong(){return 0;}};for(int i=0;i<6;i++){Question q=WholeFactorExtrema.next(id,pinned,limits,recent);assertTrue(independent.contains(q.signature()));assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);}assertEquals(0,(int)recent.get(WholeFactorExtrema.next(id,pinned,limits,recent).signature()));}assertEquals(500001500001L,WholeFactorExtrema.count(0,1000000));assertEquals(new WholeFactorExtrema.Givens(1000000,1000000),WholeFactorExtrema.read(WholeFactorExtrema.indexed("gcd",500001500000L,0,1000000)));}
 @Test public void helpRequiresStudentRemaindersAndNeverDividesByZero(){for(String id:List.of("gcd","lcm")){Question q=WholeFactorExtrema.make(id,12,18);q.answers=new String[]{"poison"};WholeFactorExtrema.attach(q);assertFalse(q.studyGuide.transfer);assertEquals("whole-factor-extrema-v1",q.studyGuide.teachingVersion);List<String>expected=id.equals("gcd")?List.of("6","0","6"):List.of("6","0","6","2","36");assertEquals(expected,q.studyGuide.frames.stream().map(f->f.expected).toList());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));for(int i=0;i<expected.size();i++)assertTrue(h.step(i).accepts(expected.get(i)));}
  for(Question q:List.of(WholeFactorExtrema.make("gcd",0,0),WholeFactorExtrema.make("lcm",0,1),WholeFactorExtrema.make("gcd",0,1))){assertFalse(q.studyGuide.transfer);assertEquals(1,q.studyGuide.frames.size());assertFalse(q.studyGuide.frames.get(0).before.contains("÷"));assertEquals(WholeFactorExtrema.undefined(q)?"0":"1",q.studyGuide.frames.get(0).expected);}
 }
 @Test public void malformedPublicPairsAndNumericInputsReject(){Question q=WholeFactorExtrema.make("gcd",12,18);assertFalse(WholeFactorExtrema.selected(new Question("gcd",q.prompt,"","6")));for(String answer:List.of("","-6","6.0","3+3","6/1","1000000000000"))assertEquals(Checker.Status.INPUT_NEEDED,WholeFactorExtrema.check(q,List.of(answer)).status);for(int bad:new int[]{-1,1000001})try{WholeFactorExtrema.make("gcd",bad,1);fail();}catch(IllegalArgumentException expected){}Question corrupted=WholeFactorExtrema.make("lcm",12,18);corrupted.prompt=corrupted.prompt.replace("12, 18","1000001, 18");assertNull(WholeFactorExtrema.read(corrupted));assertEquals(Checker.Status.INPUT_NEEDED,WholeFactorExtrema.check(corrupted,List.of("36")).status);}
}
